		var legacyValue = SimpleValueFactory.getInstance().createLiteral("legacy");
		assertEquals(Set.of("x", "missing"), row.getBindingNames());
		assertEquals(legacyValue, row.getValue("x"));
		assertFalse(row.hasBinding("missing"));
		assertFalse(rows.hasNext());

		var expected = new ListBindingSet(List.of("x"), legacyValue);
