		var restoredRow = restoredAssignment.getBindingSets().iterator().next();
		assertEquals(row, restoredRow);
		assertEquals(row.getBindingNames(), restoredRow.getBindingNames());
		assertFalse(restoredRow.hasBinding("missing"));
